// The five Validation units' bank tasks (2026-11): Presence, Type, Range, Format and Length checks, 30 practice tasks
// (3 at each level) and 8 placement tasks each. tools/add-validation-units.js adds them to tasks.json (checked by
// tools/unit-tasks.js); tools/derive-templates.js reads OVERRIDES below, so every derived template draws its input from
// both sides of the check.
//
// Levels: 1-2 predict, 3-4 fill in the blanks, 5-6 Parsons, 7 write a short check, 8 write a longer check, 9 write a
// full program, 10 a validation function. No try/except, .isalpha(), .startswith(), regular expressions, dictionaries,
// files or imports; whole numbers only; format checks are case-sensitive.
//
// A predict task names the typed input in its description ("The user types 13."). Its variants change that input (and
// say so in the description): "inputs" lists the inputs a variant can use, the task's own first, with some on each side
// of the check, and "ctx" lists linked context strings (the task's own first). Hints never give the answer, so they
// fit every variant.
// Any other task has two tests: an answer that passes the check, and one that fails it (or fails and then passes, for a
// loop that asks again). "sets" lists the pairs a variant can use (the task's own first), for tasks whose inputs are
// text; tasks with numbers are varied by tools/derive-templates.js's own rules, which keep each test on its side.
"use strict";

const T = (inputs) => ({ inputs, expected: null });
const NUMBER_WORDS = ["", "one", "two", "three", "four", "five", "six"];

// How a predict task's description names what the user typed.
function says(x) {
  if (x === "") return "just presses Enter";
  if (/^ +$/.test(x)) return "types " + NUMBER_WORDS[x.length] + " space" + (x.length > 1 ? "s" : "") + " and nothing else";
  const lead = x.length - x.trimStart().length;
  const trail = x.length - x.trimEnd().length;
  const sp = (n) => (n === 1 ? "a space" : NUMBER_WORDS[n] + " spaces");
  if (lead && trail) return "types " + x.trim() + " with " + sp(lead) + " before it and " + sp(trail) + " after it";
  if (lead) return "types " + sp(lead) + " and then " + x.trim();
  if (trail) return "types " + x.trim() + " and then " + sp(trail);
  return "types " + x;
}

// A predict task: { id, level, title, intro, code, inputs, ctx?, hints, tags, skills, wrongOutputs?, buggy? }.
function P(o) {
  const description = (o.intro ? o.intro + " " : "") + "The user " + says(o.inputs[0]) + ". What will this program print?";
  return Object.assign({ type: "predict", description, solution: o.code, tests: [T([o.inputs[0]])],
    vary: { inputs: o.inputs, ctx: o.ctx } }, strip(o, ["intro", "code", "inputs", "ctx"]));
}
// Any other task with text inputs: tests come from the first of "sets".
function S(o) {
  return Object.assign({ tests: o.sets[0].map(T), vary: { sets: o.sets, ctx: o.ctx } }, strip(o, ["sets", "ctx"]));
}
function strip(o, keys) { const c = Object.assign({}, o); for (const k of keys) delete c[k]; return c; }

// Pairs for S(): each a passing answer with a failing one (as two tests).
const pairs = (good, bad) => good.map((g, i) => [[].concat(g), [].concat(bad[i % bad.length])]);

