// ======================================================================================================
// Range checks
// ======================================================================================================
// A while loop that asks again until a number is from lo to hi (cast with int()).
const reask = (v, prompt, lo, hi, msg) => v + ' = int(input("' + prompt + '"))\nwhile ' + v + ' < ' + lo + ' or ' + v + ' > ' + hi + ':\n    print("' + msg + '")\n    ' + v + ' = int(input("' + prompt + '"))';

